def enrich():
    before = json.loads(PATH.read_text(encoding='utf-8'))
    result = copy.deepcopy(before)
    assert len(DATA) == 30
    for number, item in enumerate(DATA, 31):
        q = result['questions'][number - 1]
        assert len(item['p']) == len(item['w']) == 4
        if number in (50, 53):
            q['correct_index'] = None
            q['keyless'] = True
            q['key_source'] = 'multi-answer'
            q['tags'] = list(dict.fromkeys(q['tags'] + ['no-official-key', 'multi-answer']))
        elif number == 59:
            q['correct_index'] = 0
            q['key_source'] = 'registry-corrected'
        answers = item.get('answers', [q['correct_index']])
        q['explanation_fa'] = item['e']
        q['options_why_fa'] = [
            ('گزینه صحیح: ' if i in answers else 'دلیل رد گزینه: ') + why
            for i, why in enumerate(item['w'])
        ]
        for field, value in [('lead_fa', item['l']), ('golden_fa', item['g']), ('points_fa', item['p'])]:
            q['micro'][field] = value
    for number, (old, new) in enumerate(zip(before['questions'], result['questions']), 1):
        check = copy.deepcopy(new)
        if 31 <= number <= 60:
            for field in ('explanation_fa', 'options_why_fa'):
                check[field] = old[field]
            for field in ('lead_fa', 'golden_fa', 'points_fa'):
                check['micro'][field] = old['micro'][field]
        if number in (50, 53, 59):
            for field in ('correct_index', 'key_source', 'keyless', 'tags'):
                if field in old:
                    check[field] = old[field]
                else:
                    check.pop(field, None)
        assert check == old, f'Unauthorized change at question {number}'
    assert {k:v for k,v in result.items() if k != 'questions'} == {k:v for k,v in before.items() if k != 'questions'}
    PATH.write_text(json.dumps(result, ensure_ascii=False, indent=2) + '\n', encoding='utf-8')
    print('Enriched Q31–60; Q50/Q53 ungraded multi-answer; Q59 corrected to index 0. Stems/options unchanged.')

if __name__ == '__main__':
    enrich()
